SELECT `__typedhouse_input`.`entityId` AS `entityId`, max(`__typedhouse_input`.`version`) AS `version`, argMax(`__typedhouse_input`.`stock_index`, `__typedhouse_input`.`version`) AS `stockIndex`, argMax(`__typedhouse_input`.`lead_time_max_days`, `__typedhouse_input`.`version`) AS `leadDays` FROM (SELECT `entityId`, `version`, `stock_index`, `lead_time_max_days` FROM `metric_group_ots_component_indices` FINAL WHERE `tenantId` = {p0:String}) AS `__typedhouse_input` GROUP BY `__typedhouse_input`.`entityId`
